-- D-28 Calibration Program: FSQM-030 + FRM-705 Calibration Directory and Check Record, both DRAFT.
--
-- SQF 11.2.3.1-.6 were all Non-Compliant. Numbers from the remediation workbook: FSQM-030 reserved,
-- "FRM-7xx directory + records" -> FRM-705 (FRM-701..704 taken). Neither exists in the database.
--
-- Owner's answers, 2026-09-21: oven checked with a thermometer now and then; scales checked with test
-- weights on site; vacuum sealer has a gauge that has never been checked; keep the current probe as
-- the reference (no certified thermometer). So the program SCHEDULES AND RECORDS what the site already
-- does, adds a boiling-water check so the probe is proven at a second point, and marks the vacuum gauge
-- "Not relied on" (CCP 2 is judged by visual + pull test) rather than pretending it is calibrated.
--
-- FRM-705 is ONE ENTRY PER MONTH whose fixed, deletable rows ARE the directory (11.2.3.6): each device
-- carries its ID, use, method, tolerance (pre-filled, editable) and a per-row pop-up with how to check
-- it. The probe ice point and the YoLink sensor comparisons stay on FRM-401 under SOP-401 - those rows
-- are marked "Recorded on FRM-401" - so nothing is recorded twice and SOP-401 needs no revision.
--
-- NOT HERE (at issue): activating verification_schedule.calibration_check (planned) against FRM-705.
-- Tolerances are proposals for the owner's review.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-030', 'FRM-705')) then
    raise exception 'FSQM-030 or FRM-705 already exists.';
  end if;
  if (select count(*) from public.sop_documents
       where sop_number in ('FSQM-016', 'SOP-401', 'FRM-401', 'SOP-505', 'SOP-506', 'FRM-507', 'FRM-606',
                            'FRM-702', 'FRM-007', 'FSQM-018', 'FSQM-009', 'FSQM-017')) <> 12 then
    raise exception 'a document D-28 names does not exist.';
  end if;
  if (select status from public.verification_schedule where activity_key = 'calibration_check') <> 'planned' then
    raise exception 'calibration_check is no longer planned - check before seeding.';
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-030', 'Calibration Program', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '11.2.3.1, 11.2.3.2, 11.2.3.3, 11.2.3.4, 11.2.3.5, 11.2.3.6', true, $q${"purpose": "This program states how Adventure Bakery keeps the devices it relies on to monitor food safety accurate: which devices, what each is checked against, how often, what happens to product when one is found wrong, and how the devices are protected.", "scope": "Every measuring, testing and inspection device used to monitor a critical control point in FSQM-016, a prerequisite program, or a specification. They are listed in the directory on FRM-705. Devices used for nothing but convenience are not in scope.", "definitions": "Calibration check: comparing a device's reading with a reference of known value, and recording both.\nReference: the probe thermometer for temperature, the site's test weights for mass, a phone clock for time.\nOut of calibration: a device reading outside the tolerance stated for it on FRM-705.", "responsibility": "SQF Practitioner - owns this program and the directory, performs or oversees the monthly checks, decides what happens to product when a device fails, and is the only person who adjusts a device's calibration or an oven set point to compensate.\nProduction staff - use devices only as their SOP describes, report any device that is dropped, damaged or reads oddly, and do not use a device tagged DO NOT USE.", "procedure": ["What is calibrated", "• Every device on the FRM-705 directory: the probe thermometer, the walk-in refrigerator and freezer sensors, the oven's temperature display and bake timer, the two bench scales, and the vacuum sealer's gauge.", "• A device is added to the directory when it is bought, before it is used for monitoring, and removed only when it leaves the site (SQF 11.2.3.6).", "References and methods", "• The probe thermometer is the site's temperature reference. It is checked every month at two points: the ice point (32°F, under SOP-401, recorded on FRM-401) and boiling water (recorded on FRM-705), each within ±2°F.", "• The oven's display is checked against the probe at the centre of the rack after preheat, and passes if the oven is no more than 5°F cooler than its display. Its bake timer is checked against a phone clock over a full bake, within 30 seconds.", "• The scales are checked with the site's test weights, near the load they usually weigh, within ±1%; a scale outside that is re-calibrated with its own calibration routine as its manual describes, then checked again.", "• The refrigerator and freezer sensors are compared with the probe every month under SOP-401, within ±2°F, and recorded on FRM-401.", "> THE REFERENCE IS NOT CERTIFIED, AND THAT IS STATED RATHER THAN HIDDEN. SQF 11.2.3.2 asks for calibration against national or international standards, or, where the site does not hold them, evidence for the method it uses instead. The site holds no certified thermometer or certified weights. The two-point check is that evidence: a thermometer that reads 32°F in ice water and the boiling point in boiling water is right across the range between them, which covers the 350°F oven only by extension - so the oven's own tolerance is set on the conservative side.", "> The Team App's temperature report is software used for monitoring. It is validated each month by the same sensor comparison, because a report that agrees with the probe is reporting what the sensor measured (SQF 11.2.3.1).", "Frequency", "• Every device on the directory is checked monthly, in one session, and recorded as one FRM-705 entry.", "• A device is also checked before it is used again after it is repaired, moved, dropped or suspected of reading wrongly.", "• Where a device's manual sets a shorter interval, the manual's interval applies (SQF 11.2.3.3).", "The vacuum gauge is not relied on", "> CCP 2 is judged by a visual check of every pouch and by the pull test, not by the gauge, and the gauge has never been checked. FRM-606 records its reading without judging it. It stays on the directory, marked Not relied on, and is calibrated before any CCP 2 limit is set on it under FSQM-016.", "When a device fails", "• The device is tagged DO NOT USE and the SQF Practitioner is told the same day.", "• The SQF Practitioner decides which product was made with it since its last pass and whether that product is affected. For the oven, that means whether each bake since the last pass reached the CCP 1 limit.", "• Affected product is held on FRM-702 and dispositioned under FSQM-018; a failure of a device that monitors a CCP is also raised as a corrective action on FRM-007 under FSQM-009 (SQF 11.2.3.4).", "• The device is repaired, re-calibrated or replaced, and passes a check, before it is used again.", "Protection", "• Only the SQF Practitioner adjusts a device's calibration or an oven set point to compensate for one.", "• The probe thermometer and the test weights are kept clean and in their case or container when not in use; the scales are not moved except for cleaning, and are checked again if they are (SQF 11.2.3.5)."], "form_references": "FRM-705 - Calibration Directory and Check Record\nFRM-401 - Temperature Monitoring Review (probe ice point and sensor comparisons, under SOP-401)\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-007 - Corrective and Preventive Action record", "records": "• FRM-705 entries, one per month, reviewed and signed by the SQF Practitioner\n• FRM-401 monthly reviews for the probe ice point and the sensor comparisons\n• FRM-702 and FRM-007 records arising from a failed device\n• Service or calibration reports from an outside provider, attached to the FRM-705 entry for that month", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 11.2.3.1 to 11.2.3.6 (Calibration).\n\nFSQM-016 Food Safety Plan - CCP 1 and CCP 2, whose monitoring devices this program keeps accurate.\nSOP-401 Temperature Monitoring - where the probe's ice-point check and the sensor comparisons are performed and recorded. This program relies on them rather than repeating them.\nSOP-505 and SOP-506 - oven and scale operation.\nFSQM-018 Non-Conforming Product and Equipment, and FSQM-009 CAPA - what happens when a device fails.\nFSQM-017 Validation and Verification Program - the verification schedule's calibration activity is activated against FRM-705 when this program issues.", "revision_history": "New - 2026-09-21 - DRAFT under D-28, for the six Non-Compliant findings against 11.2.3.\n\nWHAT THE SITE DID BEFORE: the oven was checked with a thermometer from time to time and the scales with test weights on site, without a schedule or a record; the probe thermometer was ice-point checked monthly under SOP-401; the vacuum gauge was never checked. This program puts the checks that were happening on a schedule and a record, rather than inventing new ones.\n\nNO CERTIFIED REFERENCE (owner's decision, 2026-09-21): the current probe stays the reference, justified by a two-point check, with the oven tolerance set conservatively because the probe is proven only at 32°F and the boiling point.\n\nTOLERANCES ARE PROPOSED for the owner's review: oven no more than 5°F cooler than its display, timer ±30 s, scales ±1%, probe and sensors ±2°F (the last already in force under SOP-401)."}$q$::jsonb),
  ('FRM-705', 'Calibration Directory and Check Record', 'form', 'Module 11', 'draft', 'New',
   '11.2.3.6', true, jsonb_build_object('form_schema', $f${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "Calibration checks - {check_month}"}, "sections": [{"id": "about", "title": "1. How this record works", "fields": [{"id": "how_this_works", "type": "info", "label": "Calibration directory and monthly checks", "text": "THE ROWS BELOW ARE THE DIRECTORY (SQF 11.2.3.6): every device used to monitor a critical control point, a prerequisite program or a specification. One entry is made each month, and every device gets an outcome.\n\nOpen a row to see how to check it. Record what the reference read and what the device read - numbers, not just a tick.\n\nA FAIL IS NOT THE END OF THE ROW. Record what was done, and tell the SQF Practitioner the same day: product made since the last pass may need to be held (FSQM-030 Part 5).\n\nADD A DEVICE when one is bought, and delete a row only when the device leaves the site."}]}, {"id": "checks", "title": "2. Checks", "fields": [{"id": "check_month", "type": "text", "label": "Month", "width": "third", "required": true, "showInList": true, "help": "e.g. October 2026"}, {"id": "check_date", "type": "date", "label": "Date checked", "width": "third", "required": true, "defaultToday": true}, {"id": "devices", "type": "grid", "label": "Directory and results", "rowDialog": true, "rows": {"mode": "fixed", "deletable": true, "labelHeader": "Device", "addLabel": "Add device", "labels": ["Probe thermometer (site reference)", "Walk-in refrigerator sensor (YoLink)", "Walk-in freezer sensor (YoLink)", "Revent 724 oven - temperature display", "Revent 724 oven - bake timer", "Bench scale 1 - OHAUS Defender 3000 i-DT33", "Bench scale 2", "Vacuum sealer - vacuum gauge"], "defaultValues": [{"device_id": "", "used_for": "Reference for every other temperature check; FRM-401 unit checks", "method": "Ice point monthly (FRM-401); boiling water monthly (this form)", "tolerance": "Ice point 32°F ±2°F; boiling water within ±2°F of the site's boiling point"}, {"device_id": "d88b4c010010b5da", "used_for": "Cold storage PRP (SOP-401)", "method": "Compared with the probe monthly", "tolerance": "±2°F of the probe"}, {"device_id": "d88b4c010010b513", "used_for": "Cold storage PRP (SOP-401)", "method": "Compared with the probe monthly", "tolerance": "±2°F of the probe"}, {"device_id": "", "used_for": "CCP 1 (FRM-507): at least 350°F", "method": "Probe (oven-safe) at the centre of the rack after preheat, compared with the display", "tolerance": "Oven not more than 5°F cooler than its display"}, {"device_id": "", "used_for": "CCP 1 (FRM-507): at least 27 minutes", "method": "Timed against a phone clock over a full bake", "tolerance": "±30 seconds over 27 minutes"}, {"device_id": "", "used_for": "Weighing ingredients (SOP-506)", "method": "Site test weight near the usual load", "tolerance": "Within ±1% of the test weight"}, {"device_id": "", "used_for": "Weighing ingredients (SOP-506)", "method": "Site test weight near the usual load", "tolerance": "Within ±1% of the test weight"}, {"device_id": "", "used_for": "CCP 2 (FRM-606) - reading recorded, not judged", "method": "Not calibrated", "tolerance": "Not relied on"}], "guidance": ["• Ice point: done under SOP-401 and recorded on FRM-401 - mark this row 'Recorded on FRM-401' for that half.\n• Boiling water: bring water to a full rolling boil, hold the probe in it clear of the pan, let the reading settle.\n• Record the reading. The site's boiling point is written in the Tolerance column the first time and reused.\n• Outside tolerance: the probe is not used as the reference until it is replaced.", "• Done at the SOP-401 monthly review and recorded on FRM-401. Mark 'Recorded on FRM-401'.", "• Done at the SOP-401 monthly review and recorded on FRM-401. Mark 'Recorded on FRM-401'.", "• Preheat to the bake setting. Place the probe's oven-safe tip at the centre of the rack, close the door, wait for the reading to settle.\n• Record the probe reading and the display reading.\n• If the oven is more than 5°F cooler than its display: record Fail, tell the SQF Practitioner the same day. Until the oven is serviced, the set point is raised so the probe reads at least 350°F.", "• Start the phone stopwatch when the bake timer starts; stop it when the timer ends. Record both times.", "• Zero the empty, clean platform. Place the test weight in the centre. Record the reading and the test weight's marked mass.\n• Outside tolerance: tag the scale DO NOT USE and tell the SQF Practitioner. Re-calibrate with the scale's own calibration routine (manual), then check again.", "• As for bench scale 1.", "• Mark 'Not relied on'. CCP 2 is judged by the visual check and the pull test, not by this gauge.\n• The gauge is calibrated before any CCP 2 limit is set on it (FSQM-016, task 14.8)."]}, "columns": [{"id": "device_id", "type": "text", "label": "ID / serial"}, {"id": "used_for", "type": "text", "label": "Used for", "width": 2}, {"id": "method", "type": "text", "label": "Method and reference", "width": 2}, {"id": "tolerance", "type": "text", "label": "Tolerance", "width": 2}, {"id": "reference_reading", "type": "text", "label": "Reference read"}, {"id": "device_reading", "type": "text", "label": "Device read"}, {"id": "outcome", "type": "select", "label": "Outcome", "options": ["Pass", "Fail - action recorded", "Recorded on FRM-401", "Not relied on", "Not checked this month - reason recorded"], "required": true}, {"id": "action", "type": "text", "label": "Action taken", "width": 2}]}, {"id": "checked_by", "type": "signature", "label": "Checked by", "role": "filler", "required": true, "statement": "I performed the checks recorded above on the date shown."}]}, {"id": "review", "title": "3. Review", "fields": [{"id": "any_fail", "type": "select", "label": "Any device failed this month?", "width": "half", "required": true, "options": ["No", "Yes - product assessed under FSQM-030 Part 5"]}, {"id": "review_notes", "type": "textarea", "label": "Product assessed, held or released; follow-up"}, {"id": "reviewed_by", "type": "signature", "label": "Reviewed by the SQF Practitioner", "role": "verifier", "required": true, "statement": "I have reviewed these checks and any failure has been dealt with."}]}]}$f$::jsonb));

do $verify$
declare fs jsonb; g jsonb; p jsonb;
begin
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-030';
  if jsonb_array_length(p) <> 24 then raise exception 'FSQM-030 procedure is % lines, expected 24.', jsonb_array_length(p); end if;
  select content->'form_schema' into fs from public.sop_documents where sop_number = 'FRM-705';
  select f into g from jsonb_array_elements(fs->'sections') s, jsonb_array_elements(s->'fields') f where f->>'id' = 'devices';
  if jsonb_array_length(g->'rows'->'labels') <> 8 or jsonb_array_length(g->'rows'->'defaultValues') <> 8
     or jsonb_array_length(g->'rows'->'guidance') <> 8 or not (g->'rows'->>'deletable')::boolean then
    raise exception 'FRM-705 directory rows mis-built.';
  end if;
  if not exists (select 1 from jsonb_array_elements(g->'columns') c where c->>'id' = 'outcome' and (c->>'required')::boolean) then
    raise exception 'every device must get an outcome.';
  end if;
  if (select count(*) from jsonb_array_elements(fs->'sections') s, jsonb_array_elements(s->'fields') f
       where f->>'type' = 'signature' and f->>'role' = 'verifier') <> 1 then
    raise exception 'FRM-705 needs one verifier signature.';
  end if;
  raise notice 'D-28 drafts seeded: FSQM-030 (% lines), FRM-705 (8 devices).', jsonb_array_length(p);
end $verify$;

commit;
